#!/usr/bin/env python3
"""Generate test inputs for recparse. Run: python3 mkinputs.py"""
import struct, os

def rec(name: bytes, data: bytes, len_override=None):
    n = len(data) if len_override is None else len_override
    return name + b"\0" + struct.pack("<i", n) + data

os.makedirs("inputs", exist_ok=True)
w = lambda f, b: open(os.path.join("inputs", f), "wb").write(b)

# 1. A well-formed file: two records.
w("good.bin", rec(b"alice", b"hello") + rec(b"bob", bytes(range(20))))

# 2. Long name: more than 32 bytes -> stack overflow in parse_record (strcpy).
w("crash-name.bin", rec(b"A" * 200, b"x"))

# 3. Negative length: passes `len > sizeof data` because the comparison
#    is done... how? Work it out. memcpy then gets a huge size.
w("crash-neglen.bin", rec(b"eve", b"", len_override=-1))

# 4. Name of exactly 32 bytes. Harmless for the original program?
#    What about a program "fixed" with strncpy? Look at the printed name.
w("leak-name32.bin", rec(b"B" * 32, b"SECRET-DATA-IN-NEXT-FIELD-" + b"Z" * 30))

# 5. Length larger than available data but <= 64.
w("short.bin", rec(b"carol", b"abc", len_override=60)[:-0] )
EOF
